            token_fetches += 1
            return
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors='replace')
            wait = parse_wait(e.headers, body)
            if wait is not None:
                wait_for(wait)
            else:
                time.sleep(0.5)
        except Exception:
            time.sleep(0.5)

def parse_wait(headers, body):
    vals = []
    for k in ('Retry-After', 'X-Retry-In', 'X-RateLimit-Retry-After'):
        v = headers.get(k)
        if v:
            try: vals.append(float(v))
            except ValueError: pass
    try:
        obj = json.loads(body)
        for k in ('retry_after', 'retry_after_seconds', 'wait', 'wait_seconds'):
            if k in obj:
                vals.append(float(obj[k]))
    except Exception:
        pass
    if vals:
        return max(0.0, max(vals))
    m = re.search(r'(?:retry|wait)["'^0-9]*([0-9]+(?:'"\\.[0-9]+)?)', body, re.I)
    return float(m.group(1)) if m else None

def wait_for(seconds):
    global rate_limit_waits
    rate_limit_waits += 1
    time.sleep(seconds)

def get_json(path):
    global token, request_retries
    while True:
        if token is None:
            fetch_token()
        req = urllib.request.Request(BASE + path, headers={'Authorization': 'Bearer ' + token})
        try:
            with urllib.request.urlopen(req, timeout=20) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors='replace')
            request_retries += 1
            if e.code in (401, 403):
                token = None
                continue
            if e.code == 429:
                wait = parse_wait(e.headers, body)
                wait_for(wait if wait is not None else 1.0)
                continue
            wait = parse_wait(e.headers, body)
            if wait is not None:
                wait_for(wait)
            else:
                time.sleep(0.5)
        except (urllib.error.URLError, TimeoutError, OSError):
            request_retries += 1
            time.sleep(0.5)

pages = []
path = '/orders?page=1'
expected_page = 1
while path:
    data = get_json(path)
    if data.get('page') "'!= expected_page:
        raise RuntimeError(f'"'page mismatch: expected {expected_page}, got {data.get(\"page\")}')
    pages.append(data)
    if len(pages) == 1:
        total_pages = data.get('total_pages')
    elif data.get('total_pages') "'!= total_pages:
        raise RuntimeError('"'total_pages changed during listing')
    path = data.get('next')
    expected_page += 1
if len(pages) "'!= total_pages:
    raise RuntimeError(f'"'page count mismatch: fetched {len(pages)}, expected {total_pages}')

seen = set()
duplicates_skipped = 0
all_orders = []
for page in pages:
    for order in page['items']:
        oid = order['id']
        if oid in seen:
            duplicates_skipped += 1
            continue
        seen.add(oid)
        all_orders.append(order)

customers = {}
for order in all_orders:
    cid = order['customer_id']
    if cid not in customers:
        customers[cid] = get_json('/customers/' + urllib.parse.quote(cid, safe=''))

by_region = {r: 0 for r in ('north', 'south', 'east', 'west')}
qualifying = []
for order in all_orders:
    if order['status'] "'!= '"'shipped':
        continue
    ts = order['placed_at']
    if ts.endswith('Z'):
        ts = ts[:-1] + '+00:00'
    dt = datetime.fromisoformat(ts).astimezone(timezone.utc)
    if not (START <= dt < END):
        continue
    cust = customers[order['customer_id']]
    amount = Decimal(str(order['amount_cents'])) * (Decimal(100) - Decimal(str(cust['discount_pct']))) / Decimal(100)
    discounted = int(amount.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    region = cust['region']
    if region not in by_region:
        raise RuntimeError(f'unknown region {region"'!r}'"')
    by_region[region] += discounted
    qualifying.append((order['id'], order['placed_at'], order['amount_cents'], cust['discount_pct'], region, discounted))

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates_skipped,
    'by_region': by_region,
}
with open('/tmp/copper_run.json', 'w') as f:
    json.dump({'result': result, 'pages': len(pages), 'listed_items': sum(len(p['items']) for p in pages), 'distinct_items': len(all_orders), 'customers': len(customers), 'token_fetches': token_fetches, 'rate_limit_waits': rate_limit_waits, 'request_retries': request_retries, 'qualifying': qualifying}, f, indent=2)
print(json.dumps({'result': result, 'pages': len(pages), 'listed_items': sum(len(p['items']) for p in pages), 'distinct_items': len(all_orders), 'customers': len(customers), 'token_fetches': token_fetches, 'rate_limit_waits': rate_limit_waits, 'request_retries': request_retries}, indent=2))
PY"

